import{_ as s,o as a,c as t,a2 as n}from"./chunks/framework.CC4QeOx6.js";const g=JSON.parse('{"title":"What is running","description":"","frontmatter":{},"headers":[],"relativePath":"guide/status.md","filePath":"guide/status.md","lastUpdated":1795673233000}'),i={name:"guide/status.md"};function o(r,e,h,d,l,c){return a(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="what-is-running" tabindex="-1">What is running <a class="header-anchor" href="#what-is-running" aria-label="Permalink to &quot;What is running&quot;">​</a></h1><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # every project in full</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --mine</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # this project in full, one line per other project</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>running   ( on mac, lmo: this machine, and every machine work was sent to from it )</span></span>
<span class="line"><span>  guitar_2000</span></span>
<span class="line"><span>    lmo          9d41c0e2  run scripts/train_v0.py  --env lmo  41 min  running</span></span>
<span class="line"><span>    lmo          b6e07a15  run scripts/eval.py  --env lmo     3 min   running</span></span>
<span class="line"><span>  sdot-ffi</span></span>
<span class="line"><span>    lmo          3f2a9c1e  run tests/test_w2.py::*  --env lin  12 min  running</span></span>
<span class="line"><span>    jz           7c01d2aa  run train.py  --env jz            2 min   waiting: slurm job 81234 pending, 2 min</span></span>
<span class="line"><span>  lmo: windows vm 80103674 ready, 8 cpus 16G</span></span></code></pre></div><p>One command answers the question you otherwise answer with an ssh per machine, a <code>ps</code>, a <code>squeue</code> and a guess: <strong>what did I start, where, and is it still there?</strong></p><h2 id="what-it-shows" tabindex="-1">What it shows <a class="header-anchor" href="#what-it-shows" aria-label="Permalink to &quot;What it shows&quot;">​</a></h2><ul><li><strong>Runs</strong>, wherever they are: here, over ssh, in an allocation, in a container, in a Windows guest.</li><li><strong>Where a run is</strong>, when it says so with <a href="./steps"><code>errand.step</code></a>: <code>running · iteration 41 · ▕████▏ ▏ 41 %</code>.</li><li><strong>What waits</strong> for something that is not there yet, in place of <code>running</code>: <code>waiting: slurm job 81234 pending, 2 h 10</code>, <code>waiting: room on lmo: gpus (0 free of 2, needs 1)</code>, <code>waiting: windows vm 80103674 booting</code>.</li><li><strong>What is kept warm</strong>: an allocation held between commands, a Windows VM, environment agents and processes with torch already imported (<code>Preload</code>). Each is listed; with <code>--mine</code>, agents and zygotes are counted on one line.</li><li><strong>Orphans</strong>: a process whose keeper died ( each run has one, which holds it whatever becomes of the agents ). The next agent on that machine stops it.</li><li><strong>Unowned</strong> processes (Linux): something errand started that no record holds any more, an older errand&#39;s for instance. It is shown with the <code>kill</code> that stops it.</li><li><strong>Commands whose connection was lost</strong>: still running, or finished and waiting for <a href="./detached#close-the-laptop"><code>errand attach</code></a> to bring the results back.</li><li><strong><code>--batch</code> submissions</strong>, and how they are doing. → <a href="./detached">Let it run</a></li></ul><p>A machine that cannot be reached is listed as <code>cannot say</code>, with the reason, not silently skipped.</p><h2 id="stopping-a-run" tabindex="-1">Stopping a run <a class="header-anchor" href="#stopping-a-run" aria-label="Permalink to &quot;Stopping a run&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 6575aafc</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # that one, wherever it runs ( a prefix of its id is enough )</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 6575aafc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ea9ec989</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # several</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> b7f3</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                # a --batch submission, by its id</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --mine</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # everything this project runs, on every machine</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                     # at a terminal: what runs or waits, numbered; answer 1 3, 2-4 or all</span></span></code></pre></div><p>The id is the one <code>errand status</code> shows on each run&#39;s line ( with <code>--mine</code>: at the end of the line of another project ). The run is found where <code>errand status</code> finds it, then its machine&#39;s agent stops it as <code>k</code> in <code>errand tui</code> does: INT, TERM after 2 s, KILL after 5 s, to its whole process group, then what it said must happen when it stops (a Slurm job it queued is cancelled). <code>errand stop</code> comes back once it is gone, and <code>errand status</code> no longer lists it.</p><p>A run <strong>waiting</strong> for room in a machine&#39;s queue ( <code>waiting: room on node14: the machine to itself</code> ) is stopped the same way: its place in the queue goes with it, and what waited behind it moves up. This is how work left queued by a command stopped on this side is removed, without <code>errand tui</code>.</p><p>A <code>--batch</code> submission is stopped by the id it was given: its session is a process of its environment&#39;s agent like any other; a Slurm job is <code>scancel</code>led. Its record stays, with what it wrote; <code>errand forget ID</code> drops it. A process in a Windows guest, or on a node of an allocation, is not stopped from here: <code>errand vm stop</code>, <code>errand agents stop</code>, or its own command.</p><h2 id="how-it-knows" tabindex="-1">How it knows <a class="header-anchor" href="#how-it-knows" aria-label="Permalink to &quot;How it knows&quot;">​</a></h2><p>Every machine errand runs work on has an <a href="./agents">agent</a>. The agent writes down each process it starts, in its own directory, on that machine: the process group, its start time, the project.</p><p><code>errand status</code> reads those records. It reads this machine directly, and every machine work was sent to from here over one ssh each. The list of those machines is the <strong>ledger</strong>, <code>~/.cache/errand/ledger/</code>, which keeps a machine for two weeks after its last use. Nothing is started to answer: no agent, no allocation, no VM.</p><p>A Slurm allocation kept warm runs its agents on a compute node, where the login node can read neither their locks nor their processes. So for each allocation whose job runs, <code>errand status</code> asks its first node the same question, with <code>srun --overlap</code> inside the job: nothing new is asked of Slurm. Its rows show as <code>login &gt; node</code>.</p><p>Typed on a machine that runs work (a lab server, say), <code>errand status</code> shows everything its agents run, whoever started it and from wherever.</p><h3 id="the-machines-asked" tabindex="-1">The machines asked <a class="header-anchor" href="#the-machines-asked" aria-label="Permalink to &quot;The machines asked&quot;">​</a></h3><p>The machines are those work was sent to from here: errand keeps them, and forgets one after two weeks without work sent there. Looking at a machine ( <code>errand status</code>, <code>errand tui</code> ) does not keep it.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> machines</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                       # which, most recently used first</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> machines</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> forget</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> h</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # not asked any more, until work is sent there again</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> machines</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rename</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cinaps</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lab</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # shown as \`lab\`, whatever name reaches it</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> machines</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> watch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> on</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # always contacted ( auto: while work is sent there )</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> machines</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gauges</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> off</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # its CPU / memory / GPU gauges not measured; what runs there still followed</span></span></code></pre></div><p>A machine reached under several names ( <code>cinaps</code> and <code>hugo.leclerc@cinaps</code> ) is one when it says so: its agent answers an id made of the one its system was given at installation ( Linux&#39;s <code>/etc/machine-id</code>, a Mac&#39;s IOPlatformUUID, Windows&#39; MachineGuid ) and of its hostname. Two <code>node14</code> of two clusters are two machines; an id errand would keep in its own directory would not tell apart the nodes of a cluster, which share a home. Until a machine has answered it ( an older errand, a container without one ), the same ssh name but for the user, the same label, or the same hostname answered make one. It shows its oldest name, or the label it was given; two machines of one name are told apart by how they are reached. A label is refused when another machine is already known by that word, and this machine keeps its own name.</p><p>A machine no work was sent to for a day is <strong>dormant</strong>: neither <code>errand status</code> nor <code>errand tui</code> contacts it, so that no agent of errand&#39;s starts for nothing on a machine others share ( a cluster&#39;s login node ). <code>errand status</code> names it; <code>errand tui</code> shows it greyed. <code>a</code> on a dormant machine in <code>errand tui</code> or <code>errand web</code> watches it from now on; on a machine watched, <code>a</code> switches its gauges off ( or on again ): no CPU, memory or GPU measured there, what runs there followed all the same. Both are saved. <code>errand agents stop</code> contacts every machine, dormant or not.</p><p>In <code>errand tui</code>: <code>f</code> forgets the machine under the cursor, <code>r</code> names it, <code>k</code> kills what runs there, each once confirmed. Forgetting a machine stops nothing over there: <code>k</code>, or <code>errand agents stop</code>, does.</p><h2 id="stopping-work" tabindex="-1">Stopping work <a class="header-anchor" href="#stopping-work" aria-label="Permalink to &quot;Stopping work&quot;">​</a></h2><table tabindex="0"><thead><tr><th>what</th><th>how</th></tr></thead><tbody><tr><td>the command in front of you</td><td><strong>Ctrl-C</strong>. It reaches the work through every layer</td></tr><tr><td>everything kept warm ( what runs goes on )</td><td><code>errand agents stop</code></td></tr><tr><td>what matches a name</td><td><code>errand agents stop gpu</code></td></tr><tr><td>an agent, and the runs it follows with it</td><td><code>errand agents stop --force</code></td></tr><tr><td>everything, then this machine&#39;s agent and page again ( errand changed )</td><td><code>errand agents restart</code></td></tr><tr><td>Windows VMs, here and over every <code>Ssh</code></td><td><code>errand vm stop</code></td></tr><tr><td>a <code>--batch</code> submission</td><td>see <a href="./detached">Let it run</a></td></tr></tbody></table><p>Ctrl-C is handled by the agent over there, not by the errand in front of you: an interrupt first, a terminate after 2 s, a kill after 5 s, on the whole process group. It happens even if your laptop&#39;s connection is already gone. → <a href="./agents#ctrl-c-stops-the-work">Agents: Ctrl-C</a></p><h2 id="what-happens-when-something-dies" tabindex="-1">What happens when something dies <a class="header-anchor" href="#what-happens-when-something-dies" aria-label="Permalink to &quot;What happens when something dies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>what dies</th><th>what happens</th></tr></thead><tbody><tr><td>your laptop sleeps, the network drops</td><td>the work goes on; <code>errand attach</code> picks it up</td></tr><tr><td>the errand command you typed</td><td>its agent stops what it started (unless it was <code>--batch</code>)</td></tr><tr><td>an agent, by SIGTERM or a logout</td><td>it goes; what it ran goes on, each under its own keeper</td></tr><tr><td>an agent, by SIGKILL or the OOM killer</td><td>what it ran goes on, each under its own keeper; the next agent follows it again</td></tr><tr><td>a run&#39;s keeper, by SIGKILL or the OOM killer</td><td>its agent ends that run, or the next agent on that machine does</td></tr><tr><td>a VM&#39;s keeper</td><td>QEMU goes with it</td></tr><tr><td>the command waiting for a Slurm job</td><td>the job is cancelled; an allocation kept warm ends on its own once unused</td></tr></tbody></table><p>That is the rule behind the whole part: <strong>nothing errand starts runs without someone on that machine keeping track of it.</strong> The design is in <a href="https://github.com/errand-run/errand/blob/main/docs/adr/0008-nothing-runs-unowned.md" target="_blank" rel="noreferrer">ADR 0008</a> and <a href="https://github.com/errand-run/errand/blob/main/docs/adr/0009-arrivals.md" target="_blank" rel="noreferrer">ADR 0009</a>.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><p><a href="./agents">Agents and keeping warm</a> · <a href="./machine">Sharing a machine</a> · <a href="./layers/slurm">Slurm allocations</a> · <a href="./layers/windows">Windows VMs</a></p>`,31)])])}const k=s(i,[["render",o]]);export{g as __pageData,k as default};
